#include <algorithm>
#include <fstream>
#include <utility>
#include <vector>
int main() {
    std::ifstream in("reststops.in");
    std::ofstream out("reststops.out");
    int length, n, farmer, bessie;
    in >> length >> n >> farmer >> bessie;
    std::vector<std::pair<long long,long long>> stops(n);
    for (auto &stop : stops) in >> stop.first >> stop.second;
    long long answer = 0, bestTaste = 0;
    const long long advantage = farmer - bessie;
    for (int i = n-1; i >= 0; --i) {
        bestTaste = std::max(bestTaste, stops[i].second);
        const long long previous = i ? stops[i-1].first : 0;
        answer += (stops[i].first - previous) * advantage * bestTaste;
    }
    out << answer << '\n';
    return 0;
}
