#include <vector>
struct Boot { int depth, step; };
int main() {
    std::ifstream in("snowboots.in");
    std::ofstream out("snowboots.out");
    int n, b; in >> n >> b;
    std::vector<int> snow(n);
    for (int &depth : snow) in >> depth;
    std::vector<Boot> boots(b);
    for (Boot &boot : boots) in >> boot.depth >> boot.step;
    std::vector<std::vector<bool>> reached(b, std::vector<bool>(n, false));
    reached[0][0] = true;
    for (int boot = 0; boot < b; ++boot) {
        for (int tile = 0; tile < n; ++tile) if (reached[boot][tile]) {
            for (int next = tile+1; next <= std::min(n-1,tile+boots[boot].step); ++next)
                if (snow[next] <= boots[boot].depth) reached[boot][next] = true;
            for (int next = boot+1; next < b; ++next)
                if (snow[tile] <= boots[next].depth) reached[next][tile] = true;
        }
        if (reached[boot][n-1]) { out << boot << '\n'; return 0; }
    }
    return 1; // Outside the source's guaranteed-solvable domain.
}
