#include <algorithm>
#include <cstdlib>
#include <fstream>
#include <utility>
#include <vector>
int main() {
    std::ifstream in("teleport.in");
    std::ofstream out("teleport.out");
    int n; in >> n;
    long long baseline = 0;
    std::vector<std::pair<long long,long long>> events;
    for (int i = 0; i < n; ++i) {
        long long a,b; in >> a >> b;
        const long long direct = std::llabs(a-b);
        baseline += direct;
        const long long radius = direct - std::llabs(a);
        if (radius > 0) {
            events.push_back({b-radius,-1});
            events.push_back({b,2});
            events.push_back({b+radius,-1});
        }
    }
    std::sort(events.begin(),events.end());
    long long answer = baseline, cost = baseline, slope = 0;
    long long previous = events.empty() ? 0 : events.front().first;
    for (const auto &event : events) {
        cost += slope * (event.first-previous);
        answer = std::min(answer,cost);
        slope += event.second;
        previous = event.first;
    }
    out << answer << '\n';
    return 0;
}
